import { Rocketchat } from "@rocket.chat/sdk";

import Cookies from "js-cookie";

export default class RocketChatInstance {
  host = process.env.NEXT_PUBLIC_RC_URL;
  rid = "";
  rcClient = null;

  constructor(host, rid) {
    this.host = host;
    this.rid = rid;
    this.rcClient = new Rocketchat({
      protocol: "ddp",
      host: this.host,
      useSsl: !/http:\/\//.test(host),
    });
  }

  getCookies() {
    return {
      rc_token: Cookies.get("rc_token"),
      rc_uid: Cookies.get("rc_uid"),
    };
  }

  setCookies(cookies) {
    Cookies.set("rc_token", cookies.rc_token || "");
    Cookies.set("rc_uid", cookies.rc_uid || "");
  }

  async googleSSOLogin(signIn, acsCode) {
    const tokens = await signIn();
    let acsPayload = null

    if (typeof acsCode === "string") {
      acsPayload = acsCode
    }

    const payload = acsCode
      ? JSON.stringify({
        serviceName: "google",
        accessToken: tokens.access_token,
        idToken: tokens.id_token,
        expiresIn: 3600,
        totp: {
          code: acsPayload,
        },
      })
      : JSON.stringify({
        serviceName: "google",
        accessToken: tokens.access_token,
        idToken: tokens.id_token,
        expiresIn: 3600,
        scope: "profile"
      });

    try {
      const req = await fetch(`${this.host}/api/v1/login`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: payload,
      });
      const response = await req.json();

      if (response.status === "success") {
        this.setCookies({
          rc_token: response.data.authToken,
          rc_uid: response.data.userId,
        });
        if (!response.data.me.username) {
          await this.updateUserUsername(
            response.data.userId,
            response.data.me.name
          );
        }
        return { status: response.status, me: response.data.me };
      }

      if (response.error === "totp-required") {
        return response;
      }
    } catch (err) {
      console.error(err.message);
    }
  }

  async resend2FA(emailOrUsername) {
    try {
      const response = await fetch(`${this.host}/api/v1/users.2fa.sendEmailCode`, {
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": null,
          "X-User-Id": null,
        },
        mode: "cors",
        method: "POST",
        body: JSON.stringify({
          emailOrUsername: emailOrUsername,
        })
      });
      return await response.json();
    } catch (err) {
      console.error(err.message);
    }
  }

  async logout() {
    try {
      const response = await fetch(`${this.host}/api/v1/logout`, {
        headers: {
          "Content-Type": "application/json",
          "X-Auth-Token": Cookies.get("rc_token"),
          "X-User-Id": Cookies.get("rc_uid"),
        },
        method: "POST",
      });
      this.setCookies({});
      return await response.json();
    } catch (err) {
      console.error(err.message);
    }
  }
}

### Keycloak configuration
1. Create an openid-connect client in Keycloak with "confidential" as the "Access Type". See [https://www.keycloak.org/docs/latest/server_admin/#_oidc_clients](https://www.keycloak.org/docs/latest/server_admin/#_oidc_clients).

2. To add profile picture attribute received from providers, You will have to create a mapper to set profile picture url into `picture` attribute.

### Set up
We have used `next-auth` npm package to configure keycloak authentication. Read more about it [here](https://next-auth.js.org/)

1. set up environment variables for firebase config in `.env.local`

```
### BEGIN: Environment variables for keycloak
NEXTAUTH_SECRET="some random string for signing"
NEXTAUTH_URL="http://localhost:3000"
KEYCLOAK_ID='keycloak client id'
KEYCLOAK_SECRET='keycloak client secret'
KEYCLOAK_ISSUER='http://localhost:8080/realms/{Realm Name}'
### END: Environment variables for keycloak
```

2. Wrap the app with `SessionProvider` in _app.js in the following way
```
import '/styles/globals.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import Layout from '../components/layout';
import SSRProvider from 'react-bootstrap/SSRProvider';
import {SessionProvider} from 'next-auth/react';

function MyApp({ Component, pageProps: {session, ...pageProps}}) {
  return (
    <SSRProvider>
      <SessionProvider session={session}>
        <Layout menu={pageProps}>
          <Component {...pageProps} />
        </Layout>
      </SessionProvider>
    </SSRProvider>
  );
}

export default MyApp;

```
3. Add `KeycloakAuthMenuButton` in menubar.
```
...
import {KeycloakAuthMenuButton} from './auth/keycloak';
...

export default function Menubar(props) {
 ...

  return (
    <Container fluid className='border-bottom '>
      <Navbar expand='lg' className=' bg-white mx-4 my-2'>
        ...
        <div className="mx-1">
          <KeycloakAuthMenuButton/>
        </div>
      </Navbar>
    </Container>
  );
}
```
4. Use `useSession()` webhook to get user data.
```
import { useSession } from "next-auth/react";
...
...
export default Component(){
  const {data:session} = useSession();
  if(!session)
    return <div/>;
  const user = session.user;
    return <div>Hello ${user.name}</div>
}
```
5. Sign out using custom sign out function `signOutKC()`. This will sign out user from keycloak as well.

### Set up

We have used `next-auth` npm package to configure rocketchat authentication. Read more about it [here](https://next-auth.js.org/)

Before setting up rocket.chat oauth, an oauth app must be created in rocket.chat server. Then, add the callback url in the `redirect uri` list of that app. 
The callback url is `base-rc4community-url/api/auth/callback/rocket.chat`. For example, if rc4community is running on `http://localhost:3000`, then the callback url should be `http://localhost:3000/api/auth/callback/rocket.chat`.


